1	package auth
2	
3	import (
4		"context"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"os"
13		"regexp"
14		"strings"
15		"time"
16	
17		"github.com/entireio/cli/cmd/entire/cli/api"
18		"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
19		"github.com/entireio/cli/internal/entireclient/httputil"
20		"github.com/entireio/cli/internal/entireclient/userdirs"
21	)
22	
23	const (
24		cellDataAPITimeout = 30 * time.Second
25	
26		jurisdictionIdentityScope = "openid"
27	
28		// clustersAPIPath is entire-core's cluster catalog endpoint.
29		clustersAPIPath = "/api/v1/clusters"
30	)
31	
32	// jurisdictionLabelPattern bounds a home_jurisdiction claim to a single DNS
33	// label before it is substituted into a URL template. The claim rides on the
34	// login JWT (which we decode without verifying the signature) and, for the
35	// home-jurisdiction fallback path, is attacker-influenceable if a token is ever
36	// mis-minted; constraining it to [a-z0-9-] means it can only ever name a
37	// sibling jurisdiction, never inject host/scheme syntax (e.g.
38	// "us.auth.evil.tld") into jurisdictionAudience / jurisdictionCoreURL.
39	var jurisdictionLabelPattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)
40	
41	// CellTarget pins the entire-api cell a repo-scoped call must reach and the
42	// jurisdiction its identity token must be minted for. The cli layer resolves it
43	// from the repo's own cluster (via coreapi mirrors/clusters), so a repo-scoped
44	// route reaches the cell that HOSTS the repo — not the caller's home cell. A nil
45	// target falls back to home-jurisdiction routing (derived from the login JWT),
46	// which is correct for the common same-region case and for local dev.
47	type CellTarget struct {
48		// BaseURL is the cell's apiUrl to dial (e.g. https://aws-eu-west-1.api.entire.io).
49		BaseURL string
50		// Jurisdiction is the repo's cluster jurisdiction; it drives the identity
51		// token's audience and the core the exchange is performed at.
52		Jurisdiction string
53	}
54	
55	// resolveContextForCellAPI is the discovery seam for cell routing, swapped in
56	// tests. Mirrors resolveContextForAPI.
57	var resolveContextForCellAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI
58	
59	// SetResolveContextForCellAPIForTest overrides the cell-API discovery seam.
60	func SetResolveContextForCellAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
61		t.Helper()
62		prev := resolveContextForCellAPI
63		resolveContextForCellAPI = fn
64		return func() { resolveContextForCellAPI = prev }
65	}
66	
67	// cellExchangeTransportForTest, when non-nil, is the HTTP transport used for
68	// jurisdiction token exchange and cluster listing. Production leaves it nil.
69	var cellExchangeTransportForTest http.RoundTripper
70	
71	// SetCellExchangeTransportForTest overrides the transport used for jurisdiction
72	// token exchange and cluster listing, returning a restore closure — the same
73	// set/restore convention the rest of the package uses for test seams.
74	func SetCellExchangeTransportForTest(t interface{ Helper() }, rt http.RoundTripper) func() {
75		t.Helper()
76		prev := cellExchangeTransportForTest
77		cellExchangeTransportForTest = rt
78		return func() { cellExchangeTransportForTest = prev }
79	}
80	
81	// NewEntireAPICellClient returns an authenticated client aimed at an entire-api
82	// cell, carrying a jurisdictional identity token (scope=openid, aud=jurisdiction
83	// host). Repo-scoped entire-api routes do not accept the narrowed api-access
84	// bearer minted for the BFF origin — they require a cell identity token
85	// (COR-666).
86	//
87	// Cell selection, in precedence order:
88	//   - target != nil: dial target.BaseURL and mint for target.Jurisdiction. This
89	//     is the repo-scoped path — the caller (cli) resolved the repo's own cell.
90	//   - the configured data host already targets a cell (host contains ".api."):
91	//     keep that origin.
92	//   - a loopback data host (local dev): keep that origin.
93	//   - otherwise the data host is a BFF/apex: resolve the caller's home-cell
94	//     apiUrl from the cluster catalog (home-jurisdiction fallback).
95	func NewEntireAPICellClient(ctx context.Context, insecureHTTP bool, target *CellTarget) (*api.Client, error) {
96		dataURL := api.BaseURL()
97		if insecureHTTP {
98			EnableInsecureHTTP()
99		} else if err := api.RequireSecureURL(dataURL); err != nil {
100			return nil, fmt.Errorf("base URL check: %w", err)
101		}
102	
103		dataOrigin := api.OriginOnly(dataURL)
104		host, ok := hostOf(dataOrigin)
105		if !ok {
106			return nil, fmt.Errorf("data API URL %q has no host to discover against", dataURL)
107		}
108	
109		dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
110		defer cancel()
111		var httpClient *http.Client
112		switch {
113		case cellExchangeTransportForTest != nil:
114			httpClient = &http.Client{Timeout: cellDataAPITimeout, Transport: cellExchangeTransportForTest}
115		case shouldUsePlainHTTPDiscovery(dataOrigin):
116			httpClient = dataAPIDiscoveryClient(dataOrigin)
117			httpClient.Timeout = cellDataAPITimeout
118		default:
119			httpClient = &http.Client{Timeout: cellDataAPITimeout}
120		}
121	
122		selected, err := resolveContextForCellAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
123		if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
124			return nil, fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
125		}
126		if err != nil {
127			return nil, err
128		}
129	
130		// Gate the login provider's HTTPS relaxation on the core it actually dials
131		// (selected.CoreURL) plus the explicit --insecure-http-auth opt-in, matching
132		// the sibling ResolveDataAPIToken. A loopback data API must not relax HTTPS
133		// for a non-loopback core.
134		allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL)
135		loginProvider, err := NewRefreshingLoginProvider(selected, cellExchangeTransportForTest, allowInsecure)
136		if err != nil {
137			return nil, err
138		}
139	
140		loginJWT, err := loginProvider(ctx)
141		if err != nil {
142			if errors.Is(err, ErrNotLoggedIn) {
143				return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
144			}
145			// The provider already prefixes "refresh login token:"; return as-is to
146			// avoid a doubled prefix.
147			return nil, err
148		}
149	
150		jurisdiction, err := targetJurisdiction(target, loginJWT)
151		if err != nil {
152			return nil, err
153		}
154	
155		coreURL := jurisdictionCoreURL(jurisdiction, dataOrigin, selected.CoreURL)
156		if err := requireSafeExchangeURL("entire-core", coreURL); err != nil {
157			return nil, err
158		}
159	
160		cellBaseURL, err := resolveTargetCellBaseURL(ctx, target, dataOrigin, jurisdiction, coreURL, loginJWT, httpClient)
161		if err != nil {
162			return nil, err
163		}
164		if err := requireSafeExchangeURL("entire-api cell", cellBaseURL); err != nil {
165			return nil, err
166		}
167	
168		audience := jurisdictionAudience(jurisdiction, dataOrigin, selected.CoreURL)
169		token, err := exchangeJurisdictionToken(ctx, coreURL, loginJWT, audience, httpClient)
170		if err != nil {
171			return nil, fmt.Errorf("exchange jurisdictional identity token: %w", err)
172		}
173	
174		return api.NewClientWithBaseURL(token, cellBaseURL), nil
175	}
176	
177	// targetJurisdiction picks the jurisdiction to mint for: the explicit repo
178	// target when present, otherwise the caller's home jurisdiction from the login
179	// JWT. The result is validated as a DNS label before it is templated into URLs.
180	func targetJurisdiction(target *CellTarget, loginJWT string) (string, error) {
181		jurisdiction := ""
182		if target != nil {
183			jurisdiction = strings.TrimSpace(target.Jurisdiction)
184		}
185		if jurisdiction == "" {
186			var err error
187			jurisdiction, err = homeJurisdictionFromLoginJWT(loginJWT)
188			if err != nil {
189				return "", err
190			}
191		}
192		if jurisdiction == "" {
193			return "", errors.New("login token has no home_jurisdiction claim; cannot route to entire-api cell")
194		}
195		if !jurisdictionLabelPattern.MatchString(jurisdiction) {
196			return "", fmt.Errorf("jurisdiction %q is not a valid label; refusing to route", jurisdiction)
197		}
198		return jurisdiction, nil
199	}
200	
201	// resolveTargetCellBaseURL decides which cell origin to dial. See
202	// NewEntireAPICellClient's precedence doc.
203	func resolveTargetCellBaseURL(ctx context.Context, target *CellTarget, dataOrigin, jurisdiction, coreURL, loginJWT string, httpClient *http.Client) (string, error) {
204		if target != nil && strings.TrimSpace(target.BaseURL) != "" {
205			return strings.TrimRight(target.BaseURL, "/"), nil
206		}
207		if !isBFFOrigin(dataOrigin) {
208			// Already a cell URL, or a loopback local-dev host: keep it verbatim.
209			return strings.TrimRight(dataOrigin, "/"), nil
210		}
211		return resolveCellAPIBaseURL(ctx, coreURL, loginJWT, jurisdiction, httpClient)
212	}
213	
214	// isBFFOrigin reports whether origin is a BFF / apex host that fronts multiple
215	// cells (so the actual cell must be resolved from the cluster catalog), as
216	// opposed to a direct entire-api cell (host contains ".api.") or a loopback
217	// local-dev host (kept verbatim). This is environment-agnostic: it recognises
218	// prod (entire.io), staging (partial.to) and any future apex without a
219	// hardcoded domain list.
220	func isBFFOrigin(origin string) bool {
221		u, err := url.Parse(origin)
222		if err != nil || u.Host == "" {
223			return false
224		}
225		host := strings.ToLower(u.Hostname())
226		if host == "" || isLoopbackHost(host) {
227			return false
228		}
229		// A direct cell advertises itself under an ".api." label; anything else that
230		// isn't loopback is treated as a BFF/apex needing cell resolution.
231		return !strings.Contains(host, ".api.")
232	}
233	
234	func isLoopbackHost(host string) bool {
235		switch host {
236		case "localhost", "127.0.0.1", "::1":
237			return true
238		}
239		return false
240	}
241	
242	// entireDomainFamily returns the registrable apex ("entire.io" / "partial.to")
243	// derived from the discovered login core's host, or "" for loopback/custom
244	// cores. It lets the audience/core templates follow the environment the user is
245	// actually logged into (prod vs staging) instead of a hardcoded prod default.
246	func entireDomainFamily(coreURL string) string {
247		u, err := url.Parse(coreURL)
248		if err != nil {
249			return ""
250		}
251		host := strings.ToLower(u.Hostname())
252		switch {
253		case host == "partial.to" || strings.HasSuffix(host, ".partial.to"):
254			return "partial.to"
255		case host == "entire.io" || strings.HasSuffix(host, ".entire.io"):
256			return "entire.io"
257		default:
258			return ""
259		}
260	}
261	
262	// environmentFamily picks the registrable apex to template jurisdiction URLs
263	// against. The configured data host (what the user pointed the CLI at) is the
264	// most reliable signal for prod-vs-staging, so it wins; the discovered login
265	// core is the fallback.
266	func environmentFamily(dataOrigin, discoveredCore string) string {
267		if fam := entireDomainFamily(dataOrigin); fam != "" {
268			return fam
269		}
270		return entireDomainFamily(discoveredCore)
271	}
272	
273	// jurisdictionAudience returns the aud the entire-api cell for `jurisdiction`
274	// pins its identity tokens to (its jurisdiction host). Precedence:
275	//   - ENTIRE_API_AUDIENCE_TEMPLATE (with {jurisdiction}) if set;
276	//   - else https://{jurisdiction}.<family> for the environment family;
277	//   - else (loopback/custom) the data origin, best-effort and overridable.
278	//
279	// This mirrors the BFF's buildAudience(template, jurisdiction) (repos-stream.ts).
280	func jurisdictionAudience(jurisdiction, dataOrigin, discoveredCore string) string {
281		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_API_AUDIENCE_TEMPLATE")); tmpl != "" {
282			return applyJurisdictionTemplate(tmpl, jurisdiction)
283		}
284		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
285			return "https://" + jurisdiction + "." + fam
286		}
287		return strings.TrimRight(dataOrigin, "/")
288	}
289	
290	// jurisdictionCoreURL returns the entire-core origin the identity-token exchange
291	// is performed at for `jurisdiction`. Precedence:
292	//   - a loopback discovered core (local dev): honour it verbatim — the local
293	//     core signs the local login JWT, and the prod template would send the
294	//     exchange to production, which rejects the local token;
295	//   - ENTIRE_CORE_BASE_URL_TEMPLATE (with {jurisdiction}) if set;
296	//   - else https://{jurisdiction}.auth.<family> for the environment family;
297	//   - else the discovered core verbatim.
298	//
299	// This mirrors the BFF's buildCoreBaseUrl(template, jurisdiction, fallback),
300	// which honours a fallback core when the template can't produce one.
301	func jurisdictionCoreURL(jurisdiction, dataOrigin, discoveredCore string) string {
302		if isLoopbackHTTP(discoveredCore) {
303			return strings.TrimRight(discoveredCore, "/")
304		}
305		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_CORE_BASE_URL_TEMPLATE")); tmpl != "" {
306			// Apply unconditionally: applyJurisdictionTemplate is a no-op when the
307			// template has no {jurisdiction}, yielding the fixed core verbatim — the
308			// single-core case, matching the BFF's buildCoreBaseUrl and this file's
309			// own audience handling.
310			return applyJurisdictionTemplate(tmpl, jurisdiction)
311		}
312		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
313			return "https://" + jurisdiction + ".auth." + fam
314		}
315		return strings.TrimRight(discoveredCore, "/")
316	}
317	
318	func applyJurisdictionTemplate(tmpl, jurisdiction string) string {
319		return strings.ReplaceAll(strings.TrimRight(tmpl, "/"), "{jurisdiction}", jurisdiction)
320	}
321	
322	// requireSafeExchangeURL rejects a target the login JWT / identity token would
323	// be sent to unless it is https (or an explicitly-allowed loopback/insecure
324	// http). It affirmatively requires the https scheme — not merely "not http" —
325	// so ftp/ws/scheme-relative/empty targets from a buggy core catalog can't
326	// smuggle the login JWT off https. Mirrors the tokenmanager guard the sibling
327	// data_api.go relies on.
328	func requireSafeExchangeURL(label, raw string) error {
329		if insecureHTTPEnabled() || isLoopbackHTTP(raw) {
330			return nil
331		}
332		u, err := url.Parse(raw)
333		if err != nil {
334			return fmt.Errorf("%s URL check: parse %q: %w", label, raw, err)
335		}
336		if u.Scheme != "https" || u.Host == "" {
337			return fmt.Errorf("%s URL %q must be https", label, raw)
338		}
339		return nil
340	}
341	
342	func homeJurisdictionFromLoginJWT(loginJWT string) (string, error) {
343		parts := strings.Split(loginJWT, ".")
344		if len(parts) < 2 {
345			return "", errors.New("login token is not a JWT")
346		}
347		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
348		if err != nil {
349			return "", fmt.Errorf("decode login token payload: %w", err)
350		}
351		var claims struct {
352			HomeJurisdiction string `json:"home_jurisdiction"`
353		}
354		if err := json.Unmarshal(payload, &claims); err != nil {
355			return "", fmt.Errorf("parse login token payload: %w", err)
356		}
357		return claims.HomeJurisdiction, nil
358	}
359	
360	type clusterListingRow struct {
361		Jurisdiction string `json:"jurisdiction"`
362		IsDefault    bool   `json:"isDefault"`
363		APIURL       string `json:"apiUrl"`
364	}
365	
366	// resolveCellAPIBaseURL is the home-jurisdiction fallback cell resolver: it
367	// lists the caller's clusters and picks the apiUrl for `jurisdiction` (default
368	// cluster first). It hand-parses GET /api/v1/clusters rather than reusing the
369	// generated coreapi.ListClusters() because coreapi imports this (auth) package,
370	// so auth cannot import coreapi without a cycle — the repo-scoped path avoids
371	// this by resolving the cell in the cli layer (see resolveExpertsCellTarget).
372	func resolveCellAPIBaseURL(ctx context.Context, coreURL, loginJWT, jurisdiction string, httpClient *http.Client) (string, error) {
373		req, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimRight(coreURL, "/")+clustersAPIPath, nil)
374		if err != nil {
375			return "", fmt.Errorf("build clusters request: %w", err)
376		}
377		req.Header.Set("Authorization", "Bearer "+loginJWT)
378		req.Header.Set("Accept", "application/json")
379	
380		resp, err := httpClient.Do(req)
381		if err != nil {
382			return "", fmt.Errorf("list clusters: %w", err)
383		}
384		defer resp.Body.Close()
385		if resp.StatusCode != http.StatusOK {
386			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096)) //nolint:errcheck // best-effort error-detail snippet
387			return "", fmt.Errorf("list clusters: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
388		}
389	
390		var listing struct {
391			Clusters []clusterListingRow `json:"clusters"`
392		}
393		if err := json.NewDecoder(resp.Body).Decode(&listing); err != nil {
394			return "", fmt.Errorf("decode clusters response: %w", err)
395		}
396	
397		var matches []clusterListingRow
398		sawJurisdiction := false
399		for _, row := range listing.Clusters {
400			if row.Jurisdiction != jurisdiction {
401				continue
402			}
403			sawJurisdiction = true
404			if strings.TrimSpace(row.APIURL) != "" {
405				matches = append(matches, row)
406			}
407		}
408		if len(matches) == 0 {
409			if sawJurisdiction {
410				// A cluster row exists for the jurisdiction but carries no apiUrl —
411				// a schema/deploy problem, distinct from "no cell for jurisdiction".
412				return "", fmt.Errorf("cluster for jurisdiction %q advertises no apiUrl (entire-api cell not configured?)", jurisdiction)
413			}
414			return "", fmt.Errorf("no entire-api cell configured for jurisdiction %q", jurisdiction)
415		}
416		chosen := matches[0]
417		for _, row := range matches {
418			if row.IsDefault {
419				chosen = row
420				break
421			}
422		}
423		return strings.TrimRight(chosen.APIURL, "/"), nil
424	}
425	
426	func exchangeJurisdictionToken(ctx context.Context, coreURL, loginJWT, audience string, httpClient *http.Client) (string, error) {
427		if coreURL == "" {
428			return "", errors.New("no entire-core URL configured for jurisdiction token exchange")
429		}
430		form := url.Values{}
431		form.Set("grant_type", httputil.GrantTypeTokenExchange)
432		form.Set("subject_token_type", "urn:ietf:params:oauth:token-type:access_token")
433		form.Set("subject_token", loginJWT)
434		form.Set("requested_token_type", "urn:ietf:params:oauth:token-type:access_token")
435		form.Set("audience", audience)
436		form.Set("scope", jurisdictionIdentityScope)
437		form.Set("client_id", oauthClientID)
438	
439		token, _, err := httputil.PostOAuthToken(ctx, httpClient, coreURL, form)
440		if err != nil {
441			return "", fmt.Errorf("post token exchange: %w", err)
442		}
443		if strings.TrimSpace(token) == "" {
444			return "", errors.New("token exchange returned an empty access token")
445		}
446		return token, nil
447	}
