// TestEnvironmentFamilyPrefersDiscoveredCoreOverDefaultOrigin locks in the
// jurisdiction-mint fix: the data origin defaults to prod entire.io when
// ENTIRE_API_BASE_URL is unset, and that default must NOT mask a staging
// (partial.to) login. Only an EXPLICIT override wins.
func TestEnvironmentFamilyPrefersDiscoveredCoreOverDefaultOrigin(t *testing.T) {
	// Empty ENTIRE_API_BASE_URL is treated as unset (matches api.BaseURL()).
	t.Setenv("ENTIRE_API_BASE_URL", "")
	if got := environmentFamily("https://entire.io", "https://us.auth.partial.to"); got != "partial.to" {
		t.Fatalf("family = %q, want partial.to (discovered core wins over default origin)", got)
	}
	if got := environmentFamily("https://entire.io", "https://us.auth.entire.io"); got != "entire.io" {
		t.Fatalf("family = %q, want entire.io", got)
	}
	// An explicit ENTIRE_API_BASE_URL override is a deliberate choice and wins.
	t.Setenv("ENTIRE_API_BASE_URL", "https://entire.io")
	if got := environmentFamily("https://entire.io", "https://us.auth.partial.to"); got != "entire.io" {
		t.Fatalf("family = %q, want entire.io (explicit override wins)", got)
	}
}

// TestMintJurisdictionURLsFollowContextEnvironment proves the mint derives its
// audience/core from the login context's core, not a hardcoded entire.io base —
// even when a prod ENTIRE_API_BASE_URL is set (the mint passes the context core,
// not the data origin, so the override branch resolves from the context too).
func TestMintJurisdictionURLsFollowContextEnvironment(t *testing.T) {
	t.Setenv("ENTIRE_API_AUDIENCE_TEMPLATE", "")
	t.Setenv("ENTIRE_CORE_BASE_URL_TEMPLATE", "")
	t.Setenv("ENTIRE_API_BASE_URL", "https://entire.io") // prod data URL must not win

	// partial.to context → partial.to audience/core (the bug: was entire.io).
	if got := jurisdictionAudience("us", "https://us.auth.partial.to", "https://us.auth.partial.to"); got != "https://us.partial.to" {
		t.Fatalf("partial.to audience = %q, want https://us.partial.to", got)
	}
	if got := jurisdictionCoreURL("us", "https://us.auth.partial.to", "https://us.auth.partial.to"); got != "https://us.auth.partial.to" {
		t.Fatalf("partial.to core = %q, want https://us.auth.partial.to", got)
	}
	// entire.io context → entire.io (unchanged).
	if got := jurisdictionAudience("eu", "https://us.auth.entire.io", "https://us.auth.entire.io"); got != "https://eu.entire.io" {
		t.Fatalf("entire.io audience = %q, want https://eu.entire.io", got)
	}
	if got := jurisdictionCoreURL("eu", "https://us.auth.entire.io", "https://us.auth.entire.io"); got != "https://eu.auth.entire.io" {
		t.Fatalf("entire.io core = %q, want https://eu.auth.entire.io", got)
	}
}

// TestMintJurisdictionIdentityToken exercises the exchange plumbing end-to-end
// against a loopback core (honoured verbatim), asserting the posted grant/scope/
// subject/audience and the returned token.
func TestMintJurisdictionIdentityToken(t *testing.T) {
	t.Setenv("ENTIRE_API_AUDIENCE_TEMPLATE", "https://{jurisdiction}.partial.to")
	t.Setenv("ENTIRE_CORE_BASE_URL_TEMPLATE", "")

	var gotAudience, gotSubject, gotScope, gotGrant string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != oauthTokenPath {
			http.NotFound(w, r)
			return
		}
		_ = r.ParseForm() //nolint:errcheck // test handler
		gotAudience = r.FormValue("audience")
		gotSubject = r.FormValue("subject_token")
		gotScope = r.FormValue("scope")
		gotGrant = r.FormValue("grant_type")
		w.Header().Set("Content-Type", "application/json")
		_, _ = fmt.Fprint(w, `{"access_token":"juris-token","token_type":"Bearer","expires_in":3600}`)
	}))
	defer srv.Close()
	t.Cleanup(SetCellExchangeTransportForTest(t, srv.Client().Transport))

	// srv.URL is loopback → jurisdictionCoreURL honours it verbatim, so the
	// exchange reaches the test server rather than a templated prod host.
	token, audience, core, err := MintJurisdictionIdentityToken(context.Background(), srv.URL, "login-jwt", "us", true)
	if err != nil {
		t.Fatalf("MintJurisdictionIdentityToken: %v", err)
	}
	if token != "juris-token" {
		t.Errorf("token = %q, want juris-token", token)
	}
	if audience != "https://us.partial.to" {
		t.Errorf("audience = %q, want https://us.partial.to", audience)
	}
	if core != srv.URL {
		t.Errorf("exchange core = %q, want %q", core, srv.URL)
	}
	if gotAudience != "https://us.partial.to" {
		t.Errorf("posted audience = %q, want https://us.partial.to", gotAudience)
	}
	if gotSubject != "login-jwt" {
		t.Errorf("posted subject_token = %q, want login-jwt", gotSubject)
	}
	if gotScope != jurisdictionIdentityScope {
		t.Errorf("posted scope = %q, want %q", gotScope, jurisdictionIdentityScope)
	}
	if gotGrant != httputil.GrantTypeTokenExchange {
		t.Errorf("posted grant_type = %q, want %q", gotGrant, httputil.GrantTypeTokenExchange)
	}
}

func TestMintJurisdictionIdentityTokenRejectsBadInput(t *testing.T) {
	t.Parallel()
	if _, _, _, err := MintJurisdictionIdentityToken(context.Background(), "https://us.auth.partial.to", "login-jwt", "", false); err == nil {
		t.Error("empty jurisdiction should error")
	}
	if _, _, _, err := MintJurisdictionIdentityToken(context.Background(), "https://us.auth.partial.to", "login-jwt", "us.auth.evil.tld", false); err == nil {
		t.Error("non-label jurisdiction should error")
	}
	if _, _, _, err := MintJurisdictionIdentityToken(context.Background(), "https://us.auth.partial.to", "", "us", false); err == nil {
		t.Error("empty subject token should error")
	}
	if _, _, _, err := MintJurisdictionIdentityToken(context.Background(), "", "login-jwt", "us", false); err == nil {
		t.Error("empty context core should error")
	}
}

